/* DAWAH X — darimi, অধ্যায় 6 · খণ্ড 6 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][6]=[[1001,1001,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عُبَيْدٍ الْقَاسِمُ بْنُ سَلَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْحَدَّادِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ دِينَارٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ دَمِ الْحِيضَةِ يَكُونُ فِي الثَّوْبِ فَقَالَ ‏ ‏اغْسِلِيهِ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَحُكِّيهِ بِضِلَعٍ ‏","","",""],[1002,1002,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْمُبَارَكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كَرِيمَةَ ‏ ‏قالَتْ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏وَسَأَلَتْهَا امْرَأَةٌ فَقَالَتْ الْمَرْأَةُ يُصِيبُ ثَوْبَهَا مِنْ دَمِ حِيضَتِهَا فَقَالَتْ ‏ ‏لِتَغْسِلْهُ بِالْمَاءِ قَالَتْ فَإِنَّا نَغْسِلُهُ فَيَبْقَى أَثَرُهُ قَالَتْ إِنَّ الْمَاءَ طَهُورٌ ‏","","",""],[1003,1003,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تَرَى الشَّيْءَ مِنْ الْمَحِيضِ فِي ثَوْبِهَا فَتَحُتُّهُ بِالْحَجَرِ أَوْ بِالْعُودِ أَوْ بِالْقَرْنِ ثُمَّ تَرُشُّهُ ‏","","",""],[1004,1004,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَهَّابِ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ الْجُنُبِ يَعْرَقُ فِي الثَّوْبِ ثُمَّ يَمْسَحُهُ بِهِ قَالَ لَا بَأْسَ بِهِ ‏","","",""],[1005,1005,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏لَا يَرَى بِعَرَقِ الْجُنُبِ فِي الثَّوْبِ بَأْسًا ‏","","",""],[1006,1006,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّهُ كَانَ ‏ ‏لَا يَرَى بِهِ بَأْسًا ‏","","",""],[1007,1007,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏مَا كُلُّ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانُوا يَجِدُونَ ثَوْبَيْنِ فَقَالَ إِذَا اغْتَسَلْتَ أَلَسْتَ تَلْبَسُهُ فَذَاكَ بِذَاكَ ‏","","",""],[1008,1008,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏سُئِلَتْ ‏ ‏عَنْ الرَّجُلِ يُصِيبُ الْمَرْأَةَ ثُمَّ يَلْبَسُ الثَّوْبَ فَيَعْرَقُ فِيهِ فَلَمْ تَرَ بِهِ بَأْسًا ‏","","",""],[1009,1009,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏لَا بَأْسَ أَنْ يَعْرَقَ الْجُنُبُ وَالْحَائِضُ فِي الثَّوْبِ يُصَلَّى فِيهِ ‏","","",""],[1010,1010,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْجُنُبِ يَعْرَقُ فِي ثَوْبِهِ قَالَ لَا يَضُرُّهُ وَلَا يَنْضَحُهُ بِالْمَاءِ ‏","","",""],[1011,1011,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْحَائِضِ إِذَا عَرِقَتْ فِي ثِيَابِهَا فَإِنَّهُ يُجْزِئُهَا أَنْ تَنْضَحَهُ بِالْمَاءِ ‏","","",""],[1012,1012,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏كَانَ ‏ ‏يَعْرَقُ فِي الثَّوْبِ وَهُوَ جُنُبٌ ثُمَّ ‏ ‏يُصَلِّي فِيهِ ‏","","",""],[1013,1013,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ هُوَ ابْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏لَمْ يَكُنْ يَرَى بَأْسًا بِعَرَقِ الْحَائِضِ وَالْجُنُبِ ‏","","",""],[1014,1014,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا يَحِلُّ لِي مِنْ امْرَأَتِي وَهِيَ حَائِضٌ قَالَ ‏ ‏لِتَشُدَّ عَلَيْهَا إِزَارَهَا ثُمَّ شَأْنَكَ بِأَعْلَاهَا ‏","","",""],[1015,1015,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏إِلَى ‏ ‏عَائِشَةَ ‏ ‏لِيَسْأَلَهَا هَلْ يُبَاشِرُ الرَّجُلُ امْرَأَتَهُ وَهِيَ حَائِضٌ ‏ ‏فَقَالَتْ ‏ ‏لِتَشُدَّ إِزَارَهَا عَلَى أَسْفَلِهَا ثُمَّ يُبَاشِرُهَا ‏","","",""],[1016,1016,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْحَائِضُ ‏ ‏يَأْتِيهَا ‏ ‏زَوْجُهَا فِي ‏ ‏مَرَاقِّهَا ‏ ‏وَبَيْنَ فَخِذَيْهَا فَإِذَا ‏ ‏دَفَقَ ‏ ‏غَسَلَتْ مَا أَصَابَهَا وَاغْتَسَلَ هُوَ ‏","","",""],[1017,1017,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَدِيٍّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ الْكَرِيمِ ‏ ‏عَنْ الْحَائِضِ ‏ ‏فَقَالَ قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَقَدْ عَلِمَتْ ‏ ‏أُمُّ عِمْرَانَ ‏ ‏أَنِّي أَطْعُنُ فِي ‏ ‏أَلْيَتِهَا ‏ ‏يَعْنِي وَهِيَ حَائِضٌ ‏","","",""],[1018,1018,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏عَطَاءً ‏ ‏عَنْ الْحَائِضِ فَلَمْ يَرَ بِمَا دُونَ الدَّمِ بَأْسًا ‏","","",""],[1019,1019,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏إِذَا حِضْتُ أَمَرَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَّزِرُ وَكَانَ يُبَاشِرُنِي ‏","","",""],[1020,1020,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مَيْمُونُ بْنُ مِهْرَانَ ‏ ‏قَالَ ‏ ‏سُئِلَتْ ‏ ‏عَائِشَةُ ‏ ‏مَا يَحِلُّ لِلرَّجُلِ مِنْ امْرَأَتِهِ وَهِيَ حَائِضٌ قَالَتْ ‏ ‏مَا فَوْقَ الْإِزَارِ ‏","","",""],[1021,1021,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏عُيَيْنَةُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ جَوْشَنٍ ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْأَصْفَرِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا يَحِلُّ لِلرَّجُلِ مِنْ امْرَأَتِهِ إِذَا كَانَتْ حَائِضًا قَالَتْ ‏ ‏كُلُّ شَيْءٍ غَيْرُ الْجِمَاعِ قَالَ قَلْتُ فَمَا يَحْرُمُ عَلَيْهِ مِنْهَا إِذَا كَانَا مُحْرِمَيْنِ قَالَتْ كُلُّ شَيْءٍ غَيْرُ كَلَامِهَا ‏","","",""],[1022,1022,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَلْدِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لِإِنْسَانٍ ‏ ‏اجْتَنِبْ شِعَارَ الدَّمِ ‏","","",""],[1023,1023,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏إِذَا كَفَّ الْأَذَى ‏ ‏يَعْنِي الدَّمَ ‏","","",""],[1024,1024,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏لَا بَأْسَ أَنْ تُؤْتَى الْحَائِضُ بَيْنَ فَخِذَيْهَا وَفِي سُرَّتِهَا ‏","","",""],[1025,1025,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏يُقْبِلُ بِهِ وَيُدْبِرُ إِلَّا الدُّبُرَ وَالْمَحِيضَ ‏","","",""],[1026,1026,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لِحَافٍ فَوَجَدْتُ مَا تَجِدُ النِّسَاءُ فَقُمْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكِ أَنَفِسْتِ قُلْتُ وَجَدْتُ مَا تَجِدُ النِّسَاءُ قَالَ ذَاكَ مَا كَتَبَ اللَّهُ عَلَى بَنَاتِ ‏ ‏آدَمَ ‏ ‏قَالَتْ فَقُمْتُ فَأَصْلَحْتُ مِنْ شَأْنِي ثُمَّ رَجَعْتُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْخُلِي فِي اللِّحَافِ فَدَخَلْتُ ‏","","",""],[1027,1027,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏بَيْنَا أَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُضْطَجِعَةٌ فِي الْخَمِيلَةِ إِذْ حِضْتُ فَانْسَلَلْتُ فَأَخَذْتُ ثِيَابَ حِيضَتِي فَقَالَ أَنَفِسْتِ قُلْتُ نَعَمْ قَالَتْ دَعَانِي فَاضْطَجَعْتُ مَعَهُ فِي الْخَمِيلَةِ قَالَتْ وَكَانَتْ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلَانِ مِنْ الْإِنَاءِ الْوَاحِدِ مِنْ الْجَنَابَةِ وَكَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ ‏","","",""],[1028,1028,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ الْمَرْأَةَ مِنْ نِسَائِهِ فَوْقَ الْإِزَارِ وَهِيَ حَائِضٌ ‏","","",""],[1029,1029,"","","‏ ‏أَخْبَرَنَا ‏ ‏بِشْرُ بْنُ عُمَرَ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ عَمْرِو بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ إِحْدَانَا ‏ ‏إِذَا كَانَتْ حَائِضًا أَنْ تَشُدَّ عَلَيْهَا إِزَارَهَا ثُمَّ يُبَاشِرُهَا ‏","","",""],[1030,1030,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏أُمُّ الْمُؤْمِنِينَ ‏ ‏كُنْتُ ‏ ‏أَتَّزِرُ وَأَنَا حَائِضٌ ثُمَّ أَدْخُلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لِحَافِهِ ‏","","",""],[1031,1031,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏قَالَ سُئِلَ ‏ ‏ابْنُ جُبَيْرٍ ‏ ‏مَا لِلرَّجُلِ مِنْ امْرَأَتِهِ إِذَا كَانَتْ حَائِضًا قَالَ ‏ ‏مَا فَوْقَ الْإِزَارِ ‏","","",""],[1032,1032,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏فِي الْحَائِضِ قَالَ ‏ ‏الْفِرَاشُ وَاحِدٌ وَاللُّحُفُ شَتَّى فَإِنْ كَانُوا لَا يَجِدُونَ رَدَّ عَلَيْهَا مِنْ لِحَافِهِ ‏","","",""],[1033,1033,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏قَالَ لَهُ ‏ ‏مَا فَوْقَ السَّرَرِ أَوْ السُّرَّةِ ‏","","",""],[1034,1034,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بَابَنُوسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَشَّحُنِي وَأَنَا حَائِضٌ وَيُصِيبُ مِنْ رَأْسِي وَبَيْنِي وَبَيْنَهُ ثَوْبٌ ‏","","",""],[1035,1035,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏الْيَهُودَ ‏ ‏كَانُوا إِذَا حَاضَتْ الْمَرْأَةُ فِيهِمْ لَمْ يُؤَاكِلُوهَا وَلَمْ يُشَارِبُوهَا وَأَخْرَجُوهَا مِنْ الْبَيْتِ وَلَمْ تَكُنْ مَعَهُمْ فِي الْبُيُوتِ فَسُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏وَيَسْأَلُونَكَ عَنْ الْمَحِيضِ قُلْ هُوَ أَذًى ‏} ‏فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُؤَاكِلُوهُنَّ وَأَنْ يُشَارِبُوهُنَّ وَأَنْ يَكُنَّ مَعَهُمْ فِي الْبُيُوتِ وَأَنْ يَفْعَلُوا كُلَّ شَيْءٍ مَا خَلَا النِّكَاحَ فَقَالَتْ ‏ ‏الْيَهُودُ ‏ ‏مَا يُرِيدُ هَذَا أَنْ يَدَعَ شَيْئًا مِنْ أَمْرِنَا إِلَّا خَالَفَنَا فِيهِ فَجَاءَ ‏ ‏عَبَّادُ بْنُ بِشْرٍ ‏ ‏وَأُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَاهُ بِذَلِكَ وَقَالَا يَا رَسُولَ اللَّهِ أَفَلَا نَنْكِحُهُنَّ فِي الْمَحِيضِ ‏ ‏فَتَمَعَّرَ ‏ ‏وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمَعُّرًا ‏ ‏شَدِيدًا حَتَّى ظَنَنَّا أَنَّهُ وَجَدَ عَلَيْهِمَا فَقَامَا فَخَرَجَا فَاسْتَقْبَلَتْهُمَا هَدِيَّةُ لَبَنٍ فَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آثَارِهِمَا فَرَدَّهُمَا فَسَقَاهُمَا فَعَلِمْنَا أَنَّهُ لَمْ يَغْضَبْ عَلَيْهِمَا ‏","","",""],[1036,1036,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنِي ‏ ‏شَيْبَةُ بْنُ هِشَامٍ الرَّاسِبِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ الرَّجُلِ يُضَاجِعُ امْرَأَتَهُ وَهِيَ حَائِضٌ فِي لِحَافٍ وَاحِدٍ فَقَالَ ‏ ‏أَمَّا نَحْنُ آلَ ‏ ‏عُمَرَ ‏ ‏فَنَهْجُرُهُنَّ إِذَا كُنَّ حُيَّضًا ‏","","",""],[1037,1037,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَا بَأْسَ بِفَضْلِ وَضُوءِ الْمَرْأَةِ مَا لَمْ تَكُنْ جُنُبًا أَوْ حَائِضًا ‏","","",""],[1038,1038,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏غَيْلَانَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ‏ ‏يَضَعُهُ وَضْعًا ‏ ‏يَعْنِي عَلَى الْفَرْجِ ‏","","",""],[1039,1039,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏مَوْلَى ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏نُدْبَةَ ‏ ‏مَوْلَاةِ ‏ ‏مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏الْمَرْأَةَ مِنْ نِسَائِهِ وَهِيَ حَائِضٌ إِذَا كَانَ عَلَيْهَا إِزَارٌ يَبْلُغُ أَنْصَافَ الْفَخِذَيْنِ أَوْ الرُّكْبَتَيْنِ ‏ ‏مُحْتَجِزَةً ‏ ‏بِهِ ‏","","",""],[1040,1040,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُرَجِّلُ ‏ ‏رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا حَائِضٌ ‏","","",""],[1041,1041,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُرَجِّلُ ‏ ‏رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا حَائِضٌ ‏","","",""],[1042,1042,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كُنَّ جَوَارِي ‏ ‏ابْنِ عُمَرَ ‏ ‏يَغْسِلْنَ رِجْلَيْهِ وَهُنَّ حُيَّضٌ وَيُعْطِينَهُ ‏ ‏الْخُمْرَةَ ‏","","",""],[1043,1043,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُوتَى بِالْإِنَاءِ فَأَضَعُ فَمِي فَأَشْرَبُ وَأَنَا حَائِضٌ فَيَضَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَهُ عَلَى الْمَكَانِ الَّذِي وَضَعْتُ فَيَشْرَبُ ‏ ‏وَأُوتَى ‏ ‏بِالْعَرْقِ ‏ ‏فَأَنْتَهِسُ ‏ ‏فَيَضَعُ فَاهُ عَلَى الْمَكَانِ الَّذِي وَضَعْتُ ‏ ‏فَيَنْتَهِسُ ‏ ‏ثُمَّ يَأْمُرُنِي فَأَتَّزِرُ وَأَنَا حَائِضٌ وَكَانَ ‏ ‏يُبَاشِرُنِي ‏","","",""],[1044,1044,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏كَانَ يُقَالُ ‏ ‏الْحَائِضُ لَيْسَتْ الْحِيضَةُ فِي يَدِهَا تَغْسِلُ يَدَهَا وَتَعْجِنُ وَتَنْبِذُ ‏","","",""],[1045,1045,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ الْحَائِضَ حِيضَتُهَا لَيْسَتْ فِي يَدِهَا وَكَانَ يَقُولُ الْحَائِضُ حُبُّ الْحَيِّ ‏","","",""],[1046,1046,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ مُصَافَحَةِ الْيَهُودِيِّ وَالنَّصْرَانِيِّ وَالْمَجُوسِيِّ وَالْحَائِضِ فَلَمْ يَرَ فِيهِ وُضُوءًا ‏","","",""],[1047,1047,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ السُّدِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الْمَسْجِدِ فَقَالَ لِلْجَارِيَةِ نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ أَرَادَ أَنْ يَبْسُطَهَا وَيُصَلِّيَ عَلَيْهَا فَقَالَتْ إِنَّهَا حَائِضٌ فَقَالَ ‏ ‏إِنَّ حِيضَتَهَا لَيْسَ فِي يَدِهَا ‏","","",""],[1048,1048,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخْرِجُ إِلَيَّ رَأْسَهُ مِنْ الْمَسْجِدِ فَأَغْسِلُهُ ‏ ‏يَعْنِي وَهُوَ ‏ ‏مُعْتَكِفٌ ‏","","",""],[1049,1049,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏كَانَ ‏ ‏لَا يَرَى بَأْسًا أَنْ تُوَضِّئَ الْحَائِضُ الْمَرِيضَ ‏","","",""],[1050,1050,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْسِلُ رَأْسَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا حَائِضٌ ‏","","",""],[1051,1051,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَغْسِلُ رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا حَائِضٌ وَهُوَ ‏ ‏عَاكِفٌ ‏","","",""],[1052,1052,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُغِيرَةَ ‏ ‏قَالَ ‏ ‏أَرْسَلَ ‏ ‏أَبُو ظَبْيَانَ ‏ ‏إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏يَسْأَلُهُ عَنْ الْحَائِضِ تُوَضِّئُ الْمَرِيضَ قَالَ ‏ ‏نَعَمْ وَتُسْنِدُهُ قَالَ لَا فَقُلْتُ ‏ ‏لِلْمُغِيرَةِ ‏ ‏سَمِعْتَهُ مِنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ لَا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَتُسْنِدُهُ ‏ ‏يَعْنِي فِي الصَّلَاةِ ‏","","",""],[1053,1053,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ إِنِّي حَائِضٌ قَالَ ‏ ‏إِنَّهَا لَيْسَتْ فِي يَدِكِ ‏","","",""],[1054,1054,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّهُ سُئِلَ ‏ ‏عَنْ امْرَأَةٍ حَائِضٍ شَرِبَتْ مِنْ مَاءٍ أَيُتَوَضَّأُ بِهِ فَضَحِكَ وَقَالَ نَعَمْ ‏","","",""],[1055,1055,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مُؤَاكَلَةِ الْحَائِضِ قَالَ وَاكِلْهَا ‏","","",""],[1056,1056,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَأْمُرُ جَارِيَتَهُ أَنْ تُنَاوِلَهُ ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ فَتَقُولُ إِنِّي حَائِضٌ فَيَقُولُ ‏ ‏إِنَّ حِيضَتَكِ لَيْسَتْ فِي كَفِّكِ فَتُنَاوِلُهُ ‏","","",""],[1057,1057,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مُؤَاكَلَةِ الْحَائِضِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَعْضَ أَهْلِي لَحَائِضٌ وَإِنَّا لَمُتَعَشُّونَ إِنْ شَاءَ اللَّهُ جَمِيعًا ‏","","",""],[1058,1058,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏لَا ‏ ‏تَرَى بَأْسًا أَنْ تَمَسَّ الْحَائِضُ ‏ ‏الْخُمْرَةَ ‏","","",""],[1059,1059,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَيُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَعَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَحَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏فِي الْحَائِضِ إِذَا طَهُرَتْ مِنْ الدَّمِ لَا يَقْرَبُهَا زَوْجُهَا حَتَّى تَغْتَسِلَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏مِثْلَهُ سَوَاءً ‏","","",""],[1060,1060,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ سُئِلَ ‏ ‏سُفْيَانُ ‏ ‏أَيُجَامِعُ الرَّجُلُ امْرَأَتَهُ إِذَا انْقَطَعَ عَنْهَا الدَّمُ قَبْلَ أَنْ تَغْتَسِلَ فَقَالَ لَا فَقِيلَ أَرَأَيْتَ إِنْ تَرَكَتْ الْغُسْلَ يَوْمَيْنِ أَوْ أَيَّامًا قَالَ تُسْتَتَابُ ‏","","",""],[1061,1061,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ ‏} ‏قَالَ ‏ ‏حَتَّى يَنْقَطِعَ الدَّمُ ‏ { ‏فَإِذَا تَطَهَّرْنَ ‏} ‏قَالَ إِذَا اغْتَسَلْنَ ‏","","",""],[1062,1062,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏حَتَّى يَطْهُرْنَ ‏} ‏قَالَ ‏ ‏إِذَا انْقَطَعَ الدَّمُ ‏ { ‏فَإِذَا تَطَهَّرْنَ ‏} ‏قَالَ اغْتَسَلْنَ ‏","","",""],[1063,1063,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ الْأَسْوَدِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏مُجَاهِدًا ‏ ‏عَنْ امْرَأَةٍ رَأَتْ الطُّهْرَ أَيَحِلُّ لِزَوْجِهَا أَنْ ‏ ‏يَأْتِيَهَا ‏ ‏قَبْلَ أَنْ تَغْتَسِلَ قَالَ لَا حَتَّى تَحِلَّ لَهَا الصَّلَاةُ ‏","","",""],[1064,1064,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ هُوَ ابْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَطَاءً ‏ ‏وَمَيْمُونَ بْنَ مِهْرَانَ ‏ ‏وَحَدَّثَنِي ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالُوا ‏ ‏لَا ‏ ‏يَغْشَاهَا ‏ ‏حَتَّى تَغْتَسِلَ ‏","","",""],[1065,1065,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ يَطَأُ امْرَأَتَهُ وَقَدْ رَأَتْ الطُّهْرَ قَبْلَ أَنْ تَغْتَسِلَ قَالَ ‏ ‏هِيَ حَائِضٌ مَا لَمْ تَغْتَسِلْ وَعَلَيْهِ الْكَفَّارَةُ وَلَهُ أَنْ يُرَاجِعَهَا مَا لَمْ تَغْتَسِلْ ‏","","",""],[1066,1066,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَغْشَاهَا ‏ ‏زَوْجُهَا ‏","","",""],[1067,1067,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏يَقُولُ قَالَ ‏ ‏أَبُو الْخَيْرِ مَرْثَدُ بْنُ عَبْدِ اللَّهِ الْيَزَنِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏وَاللَّهِ ‏ ‏إِنِّي لَا أُجَامِعُ امْرَأَتِي فِي الْيَوْمِ الَّذِي تَطْهُرُ فِيهِ حَتَّى يَمُرَّ يَوْمٌ ‏","","",""],[1068,1068,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ ‏ ‏تَرَى الطُّهْرَ ‏ ‏أَيَأْتِيهَا ‏ ‏زَوْجُهَا قَبْلَ أَنْ تَغْتَسِلَ قَالَ لَا حَتَّى تَغْتَسِلَ ‏","","",""],[1069,1069,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ يَنْقَطِعُ عَنْهَا الدَّمُ قَالَ إِنْ أَدْرَكَهُ ‏ ‏الشَّبَقُ ‏ ‏غَسَلَتْ فَرْجَهَا ثُمَّ ‏ ‏أَتَاهَا ‏","","",""],[1070,1070,"","","‏ ‏أَخْبَرَنَا ‏ ‏فَرْوَةُ بْنُ أَبِي الْمَغْرَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَرِيكًا ‏ ‏وَسَأَلَهُ رَجُلٌ فَقَالَ الْمَرْأَةُ يَنْقَطِعُ عَنْهَا الدَّمُ ‏ ‏أَيَأْتِيهَا ‏ ‏زَوْجُهَا قَبْلَ أَنْ تَغْتَسِلَ ‏ ‏فَقَالَ قَالَ ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّهُ رَخَّصَ فِي ذَلِكَ ‏ ‏لِلشَّبِقِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَخَافُ أَنْ يَكُونَ ذَا خَطَأً أَخَافُ أَنْ يَكُونَ مِنْ حَدِيثِ ‏ ‏لَيْثٍ ‏ ‏لَا أَعْرِفُهُ مِنْ حَدِيثِ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏الشَّبِقُ الَّذِي ‏ ‏يَشْتَهِي ‏","","",""],[1071,1071,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏قَالَ زَعَمَ لَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي حُرَّةَ وَاصِلِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ نِسَاءً مِنْ نِسَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏يُصَلِّينَ فِي ‏ ‏الْخِضَابِ ‏","","",""],[1072,1072,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏سُئِلَتْ عَنْ الْمَرْأَةِ تَمْسَحُ عَلَى ‏ ‏الْخِضَابِ ‏ ‏فَقَالَتْ ‏ ‏لَأَنْ تُقْطَعَ يَدِي بِالسَّكَاكِينِ أَحَبُّ إِلَيَّ مِنْ ذَلِكَ ‏","","",""],[1073,1073,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏تُصَلِّي الْمَرْأَةُ فِي ‏ ‏الْخِضَابِ ‏ ‏قَالَتْ ‏ ‏اسْلُتِيهِ ‏ ‏وَرَغْمًا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَبُو سَعِيدٍ ‏ ‏هُوَ ‏ ‏ابْنُ أَبِي الْعَنَبْسِ ‏ ‏وَاسْمُ ‏ ‏أَبِي الْعَنَبْسِ سَعِيدُ بْنُ كَثِيرِ بْنِ عُبَيْدٍ ‏","","",""],[1074,1074,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنَّ نِسَاؤُنَا ‏ ‏يَخْتَضِبْنَ ‏ ‏بِاللَّيْلِ فَإِذَا أَصْبَحْنَ فَتَحْنَهُ فَتَوَضَّأْنَ وَصَلَّيْنَ ثُمَّ ‏ ‏يَخْتَضِبْنَ ‏ ‏بَعْدَ الصَّلَاةِ فَإِذَا كَانَ عِنْدَ الظُّهْرِ فَتَحْنَهُ فَتَوَضَّأْنَ وَصَلَّيْنَ فَأَحْسَنَّ ‏ ‏خِضَابَهُ ‏ ‏وَلَا يَمْنَعُ مِنْ الصَّلَاةِ ‏","","",""],[1075,1075,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ نِسَاءَ ‏ ‏ابْنِ عُمَرَ ‏ ‏كُنَّ ‏ ‏يَخْتَضِبْنَ ‏ ‏وَهُنَّ حُيَّضٌ ‏","","",""],[1076,1076,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنَّ نِسَاؤُنَا إِذَا صَلَّيْنَ الْعِشَاءَ الْآخِرَةَ ‏ ‏اخْتَضَبْنَ ‏ ‏فَإِذَا أَصْبَحْنَ أَطْلَقْنَهُ وَتَوَضَّأْنَ وَصَلَّيْنَ وَإِذَا صَلَّيْنَ الظُّهْرَ ‏ ‏اخْتَضَبْنَ ‏ ‏فَإِذَا أَرَدْنَ أَنْ يُصَلِّينَ الْعَصْرَ أَطْلَقْنَهُ فَأَحْسَنَّ ‏ ‏خِضَابَهُ ‏ ‏وَلَا يَحْبِسُ عَنْ الصَّلَاةِ ‏","","",""],[1077,1077,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏ح ‏ ‏و أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏فِيمَنْ ‏ ‏أَتَى أَهْلَهُ ‏ ‏وَهِيَ حَائِضٌ قَالَا ‏ ‏ذَنْبٌ أَتَاهُ يَسْتَغْفِرُ اللَّهَ وَيَتُوبُ إِلَيْهِ وَلَا يَعُودُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏الْمُثَنَّى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏مِثْلَهُ ‏","","",""],[1078,1078,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏وَأَبُو النُّعْمَانِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏ذَنْبٌ أَتَاهُ وَلَيْسَ عَلَيْهِ كَفَّارَةٌ ‏","","",""],[1079,1079,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سُئِلَ عَنْ الَّذِي ‏ ‏يَأْتِي امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ قَالَ ‏ ‏يَعْتَذِرُ إِلَى اللَّهِ وَيَتُوبُ إِلَى اللَّهِ ‏","","",""],[1080,1080,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏تَسْتَغْفِرُ اللَّهَ وَلَيْسَ عَلَيْكَ شَيْءٌ ‏ ‏يَعْنِي إِذَا ‏ ‏وَقَعَ عَلَى امْرَأَتِهِ ‏ ‏وَهِيَ حَائِضٌ ‏","","",""],[1081,1081,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْخَطَّابِ الْعَنْبِرِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ وَأَنَا أَسْمَعُ ‏ ‏عَنْ الرَّجُلِ ‏ ‏يَأْتِي امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ قَالَ يَسْتَغْفِرُ اللَّهَ ‏","","",""],[1082,1082,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقَالَ ‏ ‏رَأَيْتُ فِي الْمَنَامِ كَأَنِّي أَبُولُ دَمًا قَالَ ‏ ‏تَأْتِي امْرَأَتَكَ ‏ ‏وَهِيَ حَائِضٌ قَالَ نَعَمْ قَالَ اتَّقِ اللَّهَ وَلَا تَعُدْ ‏","","",""],[1083,1083,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏فِي الَّذِي ‏ ‏يَقَعُ عَلَى امْرَأَتِهِ ‏ ‏وَهِيَ حَائِضٌ قَالَ يَسْتَغْفِرُ اللَّهَ ‏","","",""],[1084,1084,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ‏ ‏فِي الَّذِي يُفْطِرُ يَوْمًا مِنْ رَمَضَانَ قَالَ ‏ ‏عَلَيْهِ عِتْقُ رَقَبَةٍ أَوْ ‏ ‏بَدَنَةٌ ‏ ‏أَوْ عِشْرِينَ ‏ ‏صَاعًا ‏ ‏لِأَرْبَعِينَ مِسْكِينًا وَفِي الَّذِي ‏ ‏يَغْشَى امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ مِثْلُ ذَلِكَ ‏","","",""],[1085,1085,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الَّذِي ‏ ‏يَأْتِي امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ قَالَ ‏ ‏يَتَصَدَّقُ بِنِصْفِ دِينَارٍ ‏","","",""],[1086,1086,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي الَّذِي ‏ ‏يَأْتِي امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ قَالَ ‏ ‏يَتَصَدَّقُ بِدِينَارٍ ‏ ‏أَوْ نِصْفِ دِينَارٍ شَكَّ ‏ ‏الْحَكَمُ ‏","","",""],[1087,1087,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي الَّذِي ‏ ‏يَغْشَى امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ ‏ ‏يَتَصَدَّقُ بِدِينَارٍ ‏ ‏أَوْ نِصْفِ دِينَارٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَمَّا حِفْظِي فَهُوَ مَرْفُوعٌ وَأَمَّا فُلَانٌ وَفُلَانٌ فَقَالَا غَيْرُ مَرْفُوعٍ فَقَالَ بَعْضُ الْقَوْمِ حَدِّثْنَا بِحِفْظِكَ وَدَعْ مَا قَالَ فُلَانٌ وَفُلَانٌ فَقَالَ وَاللَّهِ مَا أُحِبُّ أَنِّي عُمِّرْتُ فِي الدُّنْيَا عُمُرَ ‏ ‏نُوحٍ ‏ ‏وَأَنِّي حَدَّثْتُ بِهَذَا أَوْ سَكَتُّ عَنْ هَذَا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏عَبْدُ الحَمِيدِ بْنُ زَيْدِ بْنِ عَبْدِ الرَّحمَنِ بْنِ زَيدِ بْنِ الخَطَّابِ ‏ ‏وَكَانَ وَالِيَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَلَى ‏ ‏الْكُوفَةِ ‏","","",""],[1088,1088,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَتَاهَا ‏ ‏فِي دَمٍ فَدِينَارٌ وَإِذَا أَتَاهَا وَقَدْ انْقَطَعَ الدَّمُ فَنِصْفُ دِينَارٍ ‏","","",""],[1089,1089,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الَّذِي ‏ ‏يَقَعُ عَلَى امْرَأَتِهِ ‏ ‏وَهِيَ حَائِضٌ ‏ ‏يَتَصَدَّقُ بِنِصْفِ دِينَارٍ ‏","","",""],[1090,1090,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏امْرَأَةٌ تَكْرَهُ الْجِمَاعَ فَكَانَ إِذَا أَرَادَ أَنْ ‏ ‏يَأْتِيَهَا ‏ ‏اعْتَلَّتْ عَلَيْهِ بِالْحَيْضِ فَوَقَعَ عَلَيْهَا فَإِذَا هِيَ صَادِقَةٌ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ ‏ ‏أَنْ يَتَصَدَّقَ بِخُمُسَيْ دِينَارٍ ‏","","",""],[1091,1091,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ الرَّازِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَتَى الرَّجُلُ امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ فَإِنْ كَانَ الدَّمُ ‏ ‏عَبِيطًا ‏ ‏فَلْيَتَصَدَّقْ بِدِينَارٍ وَإِنْ كَانَتْ صُفْرَةً فَلْيَتَصَدَّقْ بِنِصْفِ دِينَارٍ ‏","","",""],[1092,1092,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ هُوَ ابْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ الَّذِي ‏ ‏يَأْتِي امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ قَالَ ‏ ‏يَتَصَدَّقُ بِدِينَارٍ أَوْ بِنِصْفِ دِينَارٍ ‏ ‏و قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏يَسْتَغْفِرُ اللَّهَ ‏","","",""],[1093,1093,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وَقَعَ عَلَى امْرَأَتِهِ ‏ ‏وَهِيَ حَائِضٌ فَعَلَيْهِ أَنْ يَتَصَدَّقَ بِدِينَارٍ ‏","","",""],[1094,1094,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي رَجُلٍ جَامَعَ امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ يَتَصَدَّقُ بِدِينَارٍ ‏","","",""],[1095,1095,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏يَتَصَدَّقُ بِدِينَارٍ أَوْ نِصْفِ دِينَارٍ ‏","","",""],[1096,1096,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏فِي رَجُلٍ ‏ ‏يَغْشَى امْرَأَتَهُ ‏ ‏وَهِيَ حَائِضٌ أَوْ رَأَتْ الطُّهْرَ وَلَمْ تَغْتَسِلْ قَالَ ‏ ‏يَسْتَغْفِرُ اللَّهَ وَيَتَصَدَّقُ بِخُمُسَيْ دِينَارٍ ‏","","",""],[1097,1097,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وَقَعَ الرَّجُلُ عَلَى امْرَأَتِهِ ‏ ‏وَهِيَ حَائِضٌ يَتَصَدَّقُ بِنِصْفِ دِينَارٍ ‏ ‏فَقَالَ لَهُ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْقَوْمِ فَإِنَّ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ‏ ‏يُعْتِقُ رَقَبَةً فَقَالَ مَا أَنْهَاكُمْ أَنْ تَقَرَّبُوا إِلَى اللَّهِ مَا اسْتَطَعْتُمْ ‏","","",""],[1098,1098,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي الَّذِي ‏ ‏يَقَعُ عَلَى امْرَأَتِهِ ‏ ‏وَهِيَ حَائِضٌ قَالَ ‏ ‏يَتَصَدَّقُ بِدِينَارٍ ‏","","",""],[1099,1099,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏ابْنِ سَابِطٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏حَفْصَةَ بِنْتَ عَبْدِ الرَّحْمَنِ هُوَ ابْنُ أَبِي بَكْرٍ ‏ ‏قُلْتُ لَهَا إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنْ شَيْءٍ وَأَنَا ‏ ‏أَسْتَحْيِي أَنْ أَسْأَلَكِ عَنْهُ قَالَتْ سَلْ يَا ابْنَ أَخِي عَمَّا بَدَا لَكَ قَالَ أَسْأَلُكِ عَنْ ‏ ‏إِتْيَانِ النِّسَاءِ ‏ ‏فِي أَدْبَارِهِنَّ ‏ ‏فَقَالَتْ حَدَّثَتْنِي ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏الْأَنْصَارُ ‏ ‏لَا ‏ ‏تُجَبِّي ‏ ‏وَكَانَتْ ‏ ‏الْمُهَاجِرُونَ ‏ ‏تُجَبِّي ‏ ‏فَتَزَوَّجَ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَبَّاهَا ‏ ‏فَأَبَتْ الْأَنْصَارِيَّةُ فَأَتَتْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهَا فَلَمَّا أَنْ جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَحْيَتْ الْأَنْصَارِيَّةُ وَخَرَجَتْ فَذَكَرَتْ ذَلِكَ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ادْعُوهَا لِي فَدُعِيَتْ لَهُ فَقَالَ لَهَا ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكَمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏سِمَامًا وَاحِدًا وَالسِّمَامُ السَّبِيلُ الْوَاحِدُ ‏","","",""],[1100,1100,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏لَقَدْ ‏ ‏عَرَضْتُ الْقُرْآنَ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏ثَلَاثَ عَرَضَاتٍ أَقِفُ عِنْدَ كُلِّ آيَةٍ أَسْأَلُهُ فِيمَ أُنْزِلَتْ وَفِيمَ كَانَتْ فَقُلْتُ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَرَأَيْتَ قَوْلَ اللَّهِ تَعَالَى ‏ { ‏فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمْ اللَّهُ ‏} ‏قَالَ مِنْ حَيْثُ أَمَرَكُمْ أَنْ تَعْتَزِلُوهُنَّ ‏","","",""],[1101,1101,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمْ اللَّهُ ‏} ‏قَالَ أُمِرُوا أَنْ يَأْتُوا مِنْ حَيْثُ نُهُوا ‏","","",""],[1102,1102,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ { ‏فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمْ اللَّهُ ‏} ‏قَالَ مِنْ قِبَلِ الطُّهْرِ ‏","","",""],[1103,1103,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْبَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُمْ مِنْ أَزْوَاجِكُمْ ‏} ‏قَالَ هُوَ وَاللَّهِ الْقُبُلُ ‏","","",""],[1104,1104,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ رَبَاحٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏قَالَ إِنَّمَا هُوَ الْفَرْجُ ‏","","",""],[1105,1105,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَلِيٍّ الرِّفَاعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ‏ ‏كَانَتْ ‏ ‏الْيَهُودُ ‏ ‏لَا ‏ ‏تَأْلُو مَا شَدَّدَتْ عَلَى الْمُسْلِمِينَ كَانُوا يَقُولُونَ يَا أَصْحَابَ ‏ ‏مُحَمَّدٍ ‏ ‏إِنَّهُ وَاللَّهِ مَا يَحِلُّ لَكُمْ أَنْ تَأْتُوا نِسَاءَكُمْ إِلَّا مِنْ وَجْهٍ وَاحِدٍ قَالَ فَأَنْزَلَ اللَّهُ ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏فَخَلَّى اللَّهُ بَيْنَ الْمُؤْمِنِينَ وَبَيْنَ حَاجَتِهِمْ ‏","","",""],[1106,1106,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ { ‏فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏قَالَ ائْتِهَا مِنْ بَيْنِ يَدَيْهَا وَمِنْ خَلْفِهَا بَعْدَ أَنْ يَكُونَ فِي الْمَأْتَى ‏","","",""],[1107,1107,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏كَانَ أَهْلُ الْجَاهِلِيَّةِ يَصْنَعُونَ فِي الْحَائِضِ نَحْوًا مِنْ صَنِيعِ ‏ ‏الْمَجُوسِ ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ ‏ { ‏وَيَسْأَلُونَكَ عَنْ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ ‏} ‏فَلَمْ يَزْدَدْ الْأَمْرُ فِيهِنَّ إِلَّا شِدَّةً ‏","","",""],[1108,1108,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏قُلْ هُوَ أَذًى ‏} ‏قَالَ هُوَ الدَّمُ ‏","","",""],[1109,1109,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ { ‏قُلْ هُوَ أَذًى ‏} ‏قَالَ قَذَرٌ ‏","","",""],[1110,1110,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏لَيْثًا ‏ ‏حَدَّثَ عَنْ ‏ ‏عِيسَى بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏قَالَ إِنْ شِئْتَ فَاعْزِلْ وَإِنْ شِئْتَ فَلَا تَعْزِلْ ‏","","",""],[1111,1111,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَلِيفَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏كَيْفَ شِئْتَ ‏ ‏يَعْنِي إِتْيَانَهَا فِي الْفَرْجِ ‏","","",""],[1112,1112,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ ‏ ‏الْيَهُودَ ‏ ‏قَالُوا لِلْمُسْلِمِينَ مَنْ ‏ ‏أَتَى امْرَأَتَهُ ‏ ‏وَهِيَ مُدْبِرَةٌ جَاءَ وَلَدُهُ أَحْوَلَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏}","","",""],[1113,1113,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ { ‏فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏قَالَ ‏ ‏يَأْتِي أَهْلَهُ ‏ ‏كَيْفَ شَاءَ قَائِمًا وَقَاعِدًا وَبَيْنَ يَدَيْهَا وَمِنْ خَلْفِهَا ‏","","",""],[1114,1114,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ الْأَشَجُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ { ‏فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمْ اللَّهُ ‏} ‏قَالَ فِي الْفَرْجِ ‏","","",""],[1115,1115,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَتَى امْرَأَتَهُ ‏ ‏فِي دُبُرِهَا فَهُوَ مِنْ الْمَرْأَةِ مِثْلُهُ مِنْ الرَّجُلِ ثُمَّ تَلَا ‏ { ‏وَيَسْأَلُونَكَ عَنْ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمْ اللَّهُ ‏} ‏أَنْ تَعْتَزِلُوهُنَّ فِي الْمَحِيضِ الْفَرْجَ ثُمَّ تَلَا ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ ‏} ‏قَائِمَةً وَقَاعِدَةً وَمُقْبِلَةً وَمُدْبِرَةً فِي الْفَرْجِ ‏","","",""],[1116,1116,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَكِيمٍ الْأَثْرَمِ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَتَى حَائِضًا أَوْ امْرَأَةً فِي دُبُرِهَا أَوْ ‏ ‏كَاهِنًا ‏ ‏فَصَدَّقَهُ بِمَا يَقُولُ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى ‏ ‏مُحَمَّدٍ ‏","","",""],[1117,1117,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الشَّقَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْقَعْقَاعِ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏آتِي امْرَأَتِي ‏ ‏حَيْثُ شِئْتُ قَالَ نَعَمْ قَالَ وَمِنْ أَيْنَ شِئْتُ قَالَ نَعَمْ قَالَ وَكَيْفَ شِئْتُ قَالَ نَعَمْ فَقَالَ لَهُ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّ هَذَا يُرِيدُ السُّوءَ قَالَ لَا ‏ ‏مَحَاشُّ ‏ ‏النِّسَاءِ عَلَيْكُمْ حَرَامٌ ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏تَقُولُ بِهِ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1118,1118,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَكْرَهُ ‏ ‏إِتْيَانَ ‏ ‏الرَّجُلِ امْرَأَتَهُ فِي دُبُرِهَا وَيَعِيبُهُ عَيْبًا شَدِيدًا ‏","","",""],[1119,1119,"","","‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ { ‏إِنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ أَحَدٍ مِنْ الْعَالَمِينَ ‏} ‏قَالَ مَا ‏ ‏نَزَى ‏ ‏ذَكَرٌ عَلَى ذَكَرٍ حَتَّى كَانَ قَوْمُ ‏ ‏لُوطٍ ‏","","",""],[1120,1120,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ مُخَلَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَتَى امْرَأَتَهُ ‏ ‏فِي دُبُرِهَا لَمْ يَنْظُرْ اللَّهُ تَعَالَى إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[1121,1121,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ حِطَّانَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ سَلَّامٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ طَلْقٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَحْدَثَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَنْصَرِفْ وَلْيَتَوَضَّأْ ثُمَّ ‏ ‏يُصَلِّي وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَأْتُوا النِّسَاءَ ‏ ‏فِي أَدْبَارِهِنَّ فَإِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏عَلِيُّ بْنُ طَلْقٍ ‏ ‏لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1122,1122,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ أَبِي الْحُبَابِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مَا تَقُولُ فِي الْجَوَارِي حِينَ أُحَمِّضُ بِهِنَّ قَالَ ‏ ‏وَمَا التَّحْمِيضُ فَذَكَرْتُ الدُّبُرَ فَقَالَ هَلْ يَفْعَلُ ذَاكَ أَحَدٌ مِنْ الْمُسْلِمِينَ ‏","","",""],[1123,1123,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ حُصَيْنٍ الْأَنْصَارِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرِو بْنِ قَيْسٍ ‏ ‏رَجُلٌ مِنْ قَوْمِي وَكَانَ مِنْ أَسْنَانِي ‏ ‏حَدَّثَنِي ‏ ‏هَرَمِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَذَاكَرْنَا شَأْنَ النِّسَاءِ فِي مَجْلِسِ ‏ ‏بَنِي وَاقِفٍ ‏ ‏وَمَا ‏ ‏يُؤْتَى مِنْهُنَّ ‏ ‏فَقَالَ ‏ ‏خُزَيْمَةُ بْنُ ثَابِتٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَيُّهَا النَّاسُ ‏ ‏إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ لَا ‏ ‏تَأْتُوا النِّسَاءَ ‏ ‏فِي ‏ ‏أَعْجَازِهِنَّ ‏","","",""],[1124,1124,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كَانُوا ‏ ‏يَجْتَنِبُونَ النِّسَاءَ فِي الْمَحِيضِ ‏ ‏وَيَأْتُونَهُنَّ ‏ ‏فِي أَدْبَارِهِنَّ فَسَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏وَيَسْأَلُونَكَ عَنْ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ ‏ ‏فَأْتُوهُنَّ ‏ ‏مِنْ حَيْثُ أَمَرَكُمْ اللَّهُ ‏} ‏فِي الْفَرْجِ وَلَا تَعْدُوهُ ‏","","",""],[1125,1125,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ بُكَيْرٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ إِسْحَقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏وَسَعِيدٍ ‏ ‏وَمُجَاهِدٍ ‏ ‏وَعَطَاءٍ ‏ ‏أَنَّهُمْ كَانُوا ‏ ‏يُنْكِرُونَ ‏ ‏إِتْيَانَ النِّسَاءِ ‏ ‏فِي أَدْبَارِهِنَّ وَيَقُولُونَ هُوَ الْكُفْرُ ‏","","",""],[1126,1126,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَالزُّهْرِيِّ ‏ ‏قَالَا ‏ ‏الْغُسْلُ مِنْ الْجَنَابَةِ وَالْحَيْضِ وَاحِدٌ ‏","","",""],[1127,1127,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ لِامْرَأَتِهِ ‏ ‏خَلِّلِي شَعْرَكِ بِالْمَاءِ قَبْلَ أَنْ تَخَلَّلَهُ نَارٌ قَلِيلَةُ الْبُقْيَا عَلَيْهِ ‏","","",""],[1128,1128,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏صَدَقَةَ بْنِ سَعِيدٍ الْحَنَفِيِّ ‏ ‏حَدَّثَنِي ‏ ‏جُمَيْعُ بْنُ عُمَيْرٍ ‏ ‏أَحَدُ ‏ ‏بَنِي تَيْمِ اللَّهِ بْنِ ثَعْلَبَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ أُمِّي وَخَالَتِي عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلَتْهَا إِحْدَاهُمَا كَيْفَ تَصْنَعِينَ عِنْدَ الْغُسْلِ فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَطَهَّرُ طُهُورَهُ لِلصَّلَاةِ وَيُفِيضُ عَلَى رَأْسِهِ ثَلَاثَ مَرَّاتٍ وَنَحْنُ نُفِيضُ عَلَى رُءُوسِنَا خَمْسًا مِنْ أَجْلِ الضَّفْرِ ‏","","",""],[1129,1129,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ زَاذِي ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْمَرْأَةِ تَغْتَسِلُ تَنْقُضُ شَعْرَهَا فَقَالَتْ ‏ ‏بَخٍ ‏ ‏وَإِنْ أَنْفَقَتْ فِيهِ ‏ ‏أُوقِيَّةً ‏ ‏إِنَّمَا يَكْفِيهَا أَنْ تُفْرِغَ عَلَى رَأْسِهَا ثَلَاثًا ‏","","",""],[1130,1130,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تُخَلِّلُهُ بِأَصَابِعِهَا ‏","","",""],[1131,1131,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏فِي الْحَائِضِ وَالْجُنُبِ يَصُبَّانِ الْمَاءَ صَبًّا وَلَا يَنْقُضَانِ شُعُورَهُمَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏مِثْلَهُ ‏","","",""],[1132,1132,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏إِذَا بَلَّتْ أُصُولَهُ وَأَطْرَافَهُ لَمْ تَنْقُضْهُ ‏","","",""],[1133,1133,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ نِسَاءَ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَأُمَّهَاتِ أَوْلَادِهِ كُنَّ إِذَا اغْتَسَلْنَ لَمْ يَنْقُضْنَ ‏ ‏عِقَصَهُنَّ ‏ ‏مِنْ حَيْضٍ وَلَا جَنَابَةٍ ‏","","",""],[1134,1134,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَا تَنْقُضْنَ ‏ ‏عِقَصَكُنَّ ‏ ‏مِنْ حَيْضٍ وَلَا مِنْ جَنَابَةٍ ‏","","",""],[1135,1135,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنِّي أَشُدُّ ضَفْرَ رَأْسِي أَوْ عُقَدَهُ قَالَ ‏ ‏احْفِنِي عَلَى رَأْسِكِ ثَلَاثَ حَفَنَاتٍ ثُمَّ ‏ ‏اغْمِزِي ‏ ‏عَلَى إِثْرِ كُلِّ حَفْنَةٍ غَمْزَةً ‏","","",""],[1136,1136,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّهُ قَالَ لِامْرَأَتِهِ ‏ ‏اسْتَأْصِلِي الشَّعْرَ ‏ ‏لَا ‏ ‏تَخَلَّلُهُ نَارٌ قَلِيلٌ بُقْيَاهَا عَلَيْهِ ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏يَعْنِي الْجَنَابَةَ ‏","","",""],[1137,1137,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّهُ قَالَ لِامْرَأَتِهِ ‏ ‏اسْتَأْصِلِي ‏ ‏الشَّعْرَ بِالْمَاءِ لَا ‏ ‏تَخَلَّلُهُ نَارٌ قَلِيلٌ بُقْيَاهَا عَلَيْهِ ‏","","",""],[1138,1138,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏إِذَا اغْتَسَلَتْ الْمَرْأَةُ مِنْ الْجَنَابَةِ فَلَا تَنْقُضْ شَعْرَهَا وَلَكِنْ تَصُبُّ الْمَاءَ عَلَى أُصُولِهِ وَتَبُلُّهُ ‏","","",""],[1139,1139,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ تُصِيبُهَا الْجَنَابَةُ وَرَأْسُهَا مَعْقُوصٌ تَحُلُّهُ قَالَ ‏ ‏لَا وَلَكِنْ تَصُبُّ عَلَى رَأْسِهَا الْمَاءَ صَبًّا حَتَّى تُرَوِّيَ أُصُولَ الشَّعْرِ ‏","","",""],[1140,1140,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمِنْهَالِ ‏ ‏حَدَّثَتْنِي ‏ ‏حَبِيبَةُ بِنْتُ حَمَّادٍ ‏ ‏حَدَّثَتْنِي ‏ ‏عَمْرَةُ بِنْتُ حَيَّانَ السَّهْمِيَّةُ ‏ ‏قَالَتْ ‏ ‏قَالَتْ لِي ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏أَمَا تَسْتَطِيعُ إِحْدَاكُنَّ إِذَا طَهُرَتْ مِنْ حَيْضِهَا أَنْ ‏ ‏تُدَخِّنَ ‏ ‏شَيْئًا مِنْ ‏ ‏قُسْطٍ ‏ ‏فَإِنْ لَمْ تَجِدْ فَشَيْئًا مِنْ ‏ ‏آسٍ ‏ ‏فَإِنْ لَمْ تَجِدْ فَشَيْئًا مِنْ ‏ ‏نَوًى ‏ ‏فَإِنْ لَمْ تَجِدْ فَشَيْئًا مِنْ مِلْحٍ ‏","","",""],[1141,1141,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِذَا اغْتَسَلَتْ الْمَرْأَةُ مِنْ الْحَيْضِ فَلْتُمِسَّ أَثَرَ الدَّمِ بِطِيبٍ ‏","","",""],[1142,1142,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نِسَاءَهُ وَأُمَّهَاتِ أَوْلَادِهِ كُنَّ يَغْتَسِلْنَ مِنْ الْحِيضَةِ وَالْجَنَابَةِ وَلَا يَنْقُضْنَ شُعُورَهُنَّ وَلَكِنْ يُبَالِغْنَ فِي بَلِّهَا ‏","","",""],[1143,1143,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَا بَأْسَ أَنْ تَتَنَاوَلَ الْحَائِضُ مِنْ الْمَسْجِدِ الشَّيْءَ ‏","","",""],[1144,1144,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏تَتَنَاوَلُ الْحَائِضُ الشَّيْءَ مِنْ الْمَسْجِدِ وَلَا تَدْخُلُهُ ‏","","",""],[1145,1145,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏الْجُنُبُ يَأْخُذُ مِنْ الْمَسْجِدِ وَلَا يَضَعُ فِيهِ ‏","","",""],[1146,1146,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْحَائِضِ ‏ ‏تَنَاوَلُ مِنْ الْمَسْجِدِ الشَّيْءَ قَالَ نَعَمْ إِلَّا الْمُصْحَفَ ‏","","",""],[1147,1147,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ ‏} ‏قَالَ هُوَ الْمُسَافِرُ ‏","","",""],[1148,1148,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَبِي جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَلْمٌ الْعَلَوِيُّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ { ‏وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ ‏} ‏قَالَ الْجُنُبُ يَجْتَازُ بِالْمَسْجِدِ وَلَا يَجْلِسُ فِيهِ ‏","","",""],[1149,1149,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏الْجُنُبُ يَمُرُّ فِي الْمَسْجِدِ وَلَا يَقْعُدُ فِيهِ ثُمَّ قَرَأَ هَذِهِ الْآيَةَ ‏ { ‏وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ ‏}","","",""],[1150,1150,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏وَسَالِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏قَالَا ‏ ‏يَمُرُّ وَلَا يَقْعُدُ فِيهِ ‏","","",""],[1151,1151,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَمْشِي فِي الْمَسْجِدِ وَنَحْنُ جُنُبٌ لَا نَرَى بِذَلِكَ بَأْسًا ‏","","",""],[1152,1152,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ الْحَائِضِ فِي عُنُقِهَا ‏ ‏التَّعْوِيذُ ‏ ‏أَوْ الْكِتَابُ قَالَ إِنْ كَانَ فِي ‏ ‏أَدِيمٍ ‏ ‏فَلْتَنْزِعْهُ وَإِنْ كَانَ فِي قَصَبَةٍ ‏ ‏مُصَاغَةٍ مِنْ فِضَّةٍ فَلَا بَأْسَ إِنْ شَاءَتْ وَضَعَتْ وَإِنْ شَاءَتْ لَمْ تَفْعَلْ ‏ ‏قِيلَ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏تَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1153,1153,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ شَوْذَبٍ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏مَطَرٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الْحَسَنَ ‏ ‏وَعَطَاءً ‏ ‏عَنْ الرَّجُلِ تَكُونُ مَعَهُ امْرَأَتُهُ فِي سَفَرٍ فَتَحِيضُ ثُمَّ تَطْهُرُ وَلَا تَجِدُ الْمَاءَ قَالَا ‏ ‏تَتَيَمَّمُ وَتُصَلِّي قَالَ قُلْتُ لَهُمَا ‏ ‏يَطَؤُهَا ‏ ‏زَوْجُهَا ‏ ‏قَالَا ‏ ‏نَعَمْ الصَّلَاةُ أَعْظَمُ مِنْ ذَلِكَ ‏","","",""],[1154,1154,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْمَرْأَةِ تَطْهُرُ وَلَا تَجِدُ الْمَاءَ قَالَ ‏ ‏يُصِيبُهَا زَوْجُهَا إِذَا تَيَمَّمَتْ ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏تَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏إِي وَاللَّهِ ‏","","",""],[1155,1155,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏فِي ‏ ‏اسْتِبْرَاءِ ‏ ‏الْأَمَةِ ‏ ‏إِنْ لَمْ تَكُنْ تَحِيضُ قَالَ خَمْسَةً وَأَرْبَعِينَ ‏","","",""],[1156,1156,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةُ أَشْهُرٍ ‏","","",""],[1157,1157,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ الرَّجُلِ ‏ ‏يَبْتَاعُ ‏ ‏الْجَارِيَةَ لَمْ تَبْلُغْ الْمَحِيضَ وَلَا تَحْمِلُ مِثْلُهَا كَمْ ‏ ‏يَسْتَبْرِئُهَا ‏ ‏قَالَ ثَلَاثَةَ أَشْهُرٍ ‏ ‏و قَالَ ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏بِخَمْسَةٍ وَأَرْبَعِينَ يَوْمًا ‏","","",""],[1158,1158,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْهَيْثَمُ بْنُ جَمِيلٍ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ بِشْرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏بِشَهْرٍ ‏ ‏سُئِلَ ‏ ‏عَبْد اللَّهِ ‏ ‏بِأَيِّهِمَا تَقُولُ ‏ ‏قَالَ ‏ ‏ثَلَاثَةُ أَشْهُرٍ أَوْثَقُ وَشَهْرٌ يَكْفِي ‏","","",""],[1159,1159,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الصَّلَوَاتِ الْمَكْتُوبَاتِ كَمَثَلِ نَهَرٍ جَارٍ عَذْبٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ ‏","","",""],[1160,1160,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ مَاذَا تَقُولُونَ ذَلِكَ مُبْقِيًا مِنْ ‏ ‏دَرَنِهِ ‏ ‏قَالُوا لَا يُبْقِي مِنْ ‏ ‏دَرَنِهِ ‏ ‏قَالَ كَذَلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ يَمْحُو اللَّهُ بِهِنَّ الْخَطَايَا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عِنْدِي أَصَحُّ ‏","","",""],[1161,1161,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَمْرِو بْنِ الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏سَأَلْنَا ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فِي زَمَنِ ‏ ‏الْحَجَّاجِ ‏ ‏وَكَانَ يُؤَخِّرُ الصَّلَاةَ عَنْ وَقْتِ الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ حِينَ تَزُولُ الشَّمْسُ وَالْعَصْرَ وَهِيَ ‏ ‏حَيَّةٌ ‏ ‏أَوْ نَقِيَّةٌ ‏ ‏وَالْمَغْرِبَ حِينَ ‏ ‏تَجِبُ ‏ ‏الشَّمْسُ وَالْعِشَاءَ رُبَّمَا عَجَّلَ وَرُبَّمَا أَخَّرَ إِذَا اجْتَمَعَ النَّاسُ عَجَّلَ وَإِذَا تَأَخَّرُوا أَخَّرَ وَالصُّبْحَ رُبَّمَا كَانُوا ‏ ‏أَوْ كَانَ ‏ ‏يُصَلِّيهَا ‏ ‏بِغَلَسٍ ‏","","",""],[1162,1162,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا فَدَخَلَ عَلَيْهِ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏فَأَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا فَدَخَلَ عَلَيْهِ ‏ ‏أَبُو مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ مَا هَذَا يَا ‏ ‏مُغِيرَةُ ‏ ‏أَلَيْسَ قَدْ عَلِمْتَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏نَزَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بِهَذَا أُمِرْتَ قَالَ اعْلَمْ مَا تُحَدِّثُ يَا ‏ ‏عُرْوَةُ ‏ ‏أَوَ أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَقَامَ وَقْتَ الصَّلَاةِ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَذَلِكَ كَانَ ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏وَلَقَدْ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا قَبْلَ أَنْ تَظْهَرَ ‏","","",""],[1163,1163,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏قَالَ ‏ ‏وَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ قَدِمَهَا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي ‏ ‏الْمَدِينَةَ ‏ ‏إِنَّمَا يُجْتَمَعُ إِلَيْهِ بِالصَّلَاةِ لِحِينِ مَوَاقِيتِهَا بِغَيْرِ دَعْوَةٍ فَهَمَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَجْعَلَ بُوقًا كَبُوقِ ‏ ‏الْيَهُودِ ‏ ‏الَّذِينَ يَدْعُونَ بِهِ لِصَلَاتِهِمْ ثُمَّ كَرِهَهُ ثُمَّ أَمَرَ ‏ ‏بِالنَّاقُوسِ ‏ ‏فَنُحِتَ لِيُضْرَبَ بِهِ لِلْمُسْلِمِينَ إِلَى الصَّلَاةِ فَبَيْنَمَا هُمْ عَلَى ذَلِكَ إِذْ رَأَى ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدِ بْنِ عَبْدِ رَبِّهِ ‏ ‏أَخُو ‏ ‏بَلْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُ طَافَ ‏ ‏بِيَ اللَّيْلَةَ طَائِفٌ مَرَّ بِي رَجُلٌ عَلَيْهِ ثَوْبَانِ أَخْضَرَانِ يَحْمِلُ ‏ ‏نَاقُوسًا ‏ ‏فِي يَدِهِ فَقُلْتُ يَا عَبْدَ اللَّهِ أَتَبِيعُ هَذَا ‏ ‏النَّاقُوسَ ‏ ‏فَقَالَ وَمَا تَصْنَعُ بِهِ قُلْتُ ‏ ‏نَدْعُو بِهِ إِلَى الصَّلَاةِ قَالَ أَفَلَا أَدُلُّكَ عَلَى خَيْرٍ مِنْ ذَلِكَ قُلْتُ وَمَا هُوَ قَالَ تَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ حَيَّ عَلَى الْفَلَاحِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ ثُمَّ اسْتَأْخَرَ غَيْرَ كَثِيرٍ ثُمَّ قَالَ مِثْلَ مَا قَالَ وَجَعَلَهَا وِتْرًا إِلَّا أَنَّهُ قَالَ قَدْ قَامَتْ الصَّلَاةُ قَدْ قَامَتْ الصَّلَاةُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ فَلَمَّا خُبِّرَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَرُؤْيَا حَقٌّ إِنْ شَاءَ اللَّهُ فَقُمْ مَعَ ‏ ‏بِلَالٍ ‏ ‏فَأَلْقِهَا عَلَيْهِ فَإِنَّهُ ‏ ‏أَنْدَى ‏ ‏صَوْتًا مِنْكَ فَلَمَّا أَذَّنَ ‏ ‏بِلَالٌ ‏ ‏سَمِعَهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَهُوَ فِي بَيْتِهِ فَخَرَجَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَجُرُّ إِزَارَهُ وَهُوَ يَقُولُ يَا نَبِيَّ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ رَأَيْتُ مِثْلَ مَا رَأَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلِلَّهِ الْحَمْدُ فَذَاكَ أَثْبَتُ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِيهِ ‏ ‏سَلَمَةُ ‏ ‏قَالَ حَدَّثَنِيهِ ‏ ‏ابْنُ إِسْحَقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هَذَا الْحَدِيثَ ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَبْدِ رَبِّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاقُوسِ ‏ ‏فَذَكَرَ ‏ ‏نَحْوَهُ ‏","","",""],[1164,1164,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏يَرْفَعُهُ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[1165,1165,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَعَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤَذِّنَانِ ‏ ‏بِلَالٌ ‏ ‏وَابْنُ أُمِّ مَكْتُومٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى تَسْمَعُوا أَذَانَ ‏ ‏ابْنِ أُمِّ مَكْتُومٍ ‏ ‏فَقَالَ ‏ ‏الْقَاسِمُ ‏ ‏وَمَا كَانَ بَيْنَهُمَا إِلَّا أَنْ يَنْزِلَ هَذَا ‏ ‏وَيَرْقَى هَذَا ‏","","",""],[1166,1166,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ بْنِ فَارِسٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عُمَرَ بْنِ سَعْدٍ الْمُؤَذِّنِ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏كَانَ يُؤَذِّنُ فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَفْصٌ ‏ ‏حَدَّثَنِي ‏ ‏أَهْلِي ‏ ‏أَنَّ ‏ ‏بِلَالًا ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْذِنُهُ لِصَلَاةِ الْفَجْرِ فَقَالُوا إِنَّهُ نَائِمٌ فَنَادَى ‏ ‏بِلَالٌ ‏ ‏بِأَعْلَى صَوْتِهِ ‏ ‏الصَّلَاةُ خَيْرٌ مِنْ النَّوْمِ فَأُقِرَّتْ فِي أَذَانِ صَلَاةِ الْفَجْرِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يُقَالُ ‏ ‏سَعْدٌ الْقَرَظُ ‏","","",""],[1167,1167,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ أَبِي الْمُثَنَّى ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثْنَى مَثْنَى وَالْإِقَامَةُ مَرَّةً مَرَّةً غَيْرَ أَنَّهُ كَانَ إِذَا قَالَ قَدْ قَامَتْ الصَّلَاةُ قَالَهَا مَرَّتَيْنِ فَإِذَا سَمِعْنَا الْإِقَامَةَ تَوَضَّأَ أَحَدُنَا وَخَرَجَ ‏","","",""],[1168,1168,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَيُوتِرَ الْإِقَامَةَ ‏","","",""],[1169,1169,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ ‏ ‏وَيُوتِرَ ‏ ‏الْإِقَامَةَ إِلَّا الْإِقَامَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏نَحْوَهُ ‏","","",""],[1170,1170,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏ابْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ نَحْوًا مِنْ عِشْرِينَ رَجُلًا فَأَذَّنُوا فَأَعْجَبَهُ صَوْتُ ‏ ‏أَبِي مَحْذُورَةَ ‏ ‏فَعَلَّمَهُ الْأَذَانَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَه إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ حَيَّ عَلَى الْفَلَاحِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَالْإِقَامَةَ مَثْنَى مَثْنَى ‏","","",""],[1171,1171,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏وَحَجَّاجُ بْنُ الْمِنْهَالِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ الْأَحْوَلُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَامِرُ بْنُ عَبْدِ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَكْحُولٌ ‏ ‏أَنَّ ‏ ‏ابْنَ مُحَيْرِيزٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا مَحْذُورَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَهُ الْأَذَانَ تِسْعَ عَشْرَةَ كَلِمَةً وَالْإِقَامَةَ سَبْعَ عَشْرَةَ كَلِمَةً ‏","","",""],[1172,1172,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ رَأَى ‏ ‏بِلَالًا ‏ ‏أَذَّنَ قَالَ ‏ ‏فَجَعَلْتُ أَتْبَعُ فَاهُ هَاهُنَا وَهَاهُنَا بِالْأَذَانِ ‏","","",""],[1173,1173,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏بِلَالًا ‏ ‏رَكَزَ ‏ ‏الْعَنَزَةَ ‏ ‏ثُمَّ أَذَّنَ وَوَضَعَ أُصْبُعَيْهِ فِي أُذُنَيْهِ فَرَأَيْتُهُ يَدُورُ فِي أَذَانِهِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدِيثُ ‏ ‏الثَّوْرِيِّ ‏ ‏أَصَحُّ ‏","","",""],[1174,1174,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى هُوَ ابْنُ يَعْقُوبَ الزَّمْعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمِ بْنُ دِينَارٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَهْلُ بْنُ سَعْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثِنْتَانِ لَا تُرَدَّانِ ‏ ‏أَوْ قَلَّ مَا تُرَدَّانِ ‏ ‏الدُّعَاءُ عِنْدَ النِّدَاءِ وَعِنْدَ ‏ ‏الْبَأْسِ ‏ ‏حِينَ ‏ ‏يُلْحِمُ ‏ ‏بَعْضُهُ بَعْضًا ‏","","",""],[1175,1175,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ ‏","","",""],[1176,1176,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَنَادَى الْمُنَادِي فَقَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ قَالَ أَشْهَدُ أَنْ لَا إِلَه إِلَّا اللَّهُ قَالَ وَأَنَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قَالَ وَأَنَا أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَأَخْبَرَنِي ‏ ‏بَعْضُ أَصْحَابِنَا ‏ ‏أَنَّهُ لَمَّا قَالَ حَيَّ عَلَى الصَّلَاةِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ثُمَّ قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏سَمِعْتُ نَبِيَّكُمْ يَقُولُ هَذَا ‏","","",""],[1177,1177,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏سَمِعَ الْمُؤَذِّنَ قَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ الْمُؤَذِّنُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ الْمُؤَذِّنُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَقَالَ الْمُؤَذِّنُ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ فَقَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَقَالَ الْمُؤَذِّنُ حَيَّ عَلَى الْفَلَاحِ حَيَّ عَلَى الْفَلَاحِ فَقَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَقَالَ الْمُؤَذِّنُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ ثُمَّ قَالَ هَكَذَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1178,1178,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا نُودِيَ بِالصَّلَاةِ أَدْبَرَ الشَّيْطَانُ لَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الْأَذَانَ فَإِذَا قُضِيَ الْأَذَانُ أَقْبَلَ وَإِذَا ‏ ‏ثُوِّبَ ‏ ‏أَدْبَرَ فَإِذَا قُضِيَ ‏ ‏التَّثْوِيبُ ‏ ‏أَقْبَلَ حَتَّى ‏ ‏يَخْطِرَ ‏ ‏بَيْنَ الْمَرْءِ وَنَفْسِهِ فَيَقُولُ اذْكُرْ كَذَا وَكَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ قَبْلَ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏ثُوِّبَ ‏ ‏يَعْنِي أُقِيمَ ‏","","",""],[1179,1179,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ الْمُحَارِبِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَأَى رَجُلًا خَرَجَ مِنْ الْمَسْجِدِ بَعْدَ مَا أَذَّنَ الْمُؤَذِّنُ فَقَالَ أَمَّا هَذَا فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏","","",""],[1180,1180,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ حِينَ زَاغَتْ الشَّمْسُ فَصَلَّى بِهِمْ صَلَاةَ الظُّهْرِ ‏","","",""],[1181,1181,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا عِنْدِي عَلَى التَّأْخِيرِ إِذَا تَأَذَّوْا بِالْحَرِّ ‏","","",""],[1182,1182,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعَصْرَ ثُمَّ يَذْهَبُ الذَّاهِبُ إِلَى ‏ ‏الْعَوَالِي ‏ ‏فَيَأْتِيهَا وَالشَّمْسُ مُرْتَفِعَةٌ ‏","","",""],[1183,1183,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ هُوَ ابْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَغْرِبَ سَاعَةَ تَغْرُبُ الشَّمْسُ إِذَا غَابَ ‏ ‏حَاجِبُهَا ‏","","",""],[1184,1184,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏الْعَبَّاسِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَزَالُ أُمَّتِي بِخَيْرٍ مَا لَمْ يَنْتَظِرُوا بِالْمَغْرِبِ اشْتِبَاكَ النُّجُومِ ‏","","",""],[1185,1185,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏وَاللَّهِ إِنِّي لَأَعْلَمُ النَّاسِ بِوَقْتِ هَذِهِ الصَّلَاةِ ‏ ‏يَعْنِي صَلَاةَ الْعِشَاءِ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهَا لِسُقُوطِ الْقَمَرِ لِثَالِثَةٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَمَلَّهُ عَلَيْنَا مِنْ كِتَابِهِ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ ثَابِتٍ ‏","","",""],[1186,1186,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏وَعَمْرُو بْنُ عَاصِمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ ذَاتَ لَيْلَةٍ حَتَّى كَادَ أَنْ يَذْهَبَ ثُلُثُ اللَّيْلِ أَوْ قَرِيبُهُ فَجَاءَ وَالنَّاسُ رُقَّدٌ وَهُمْ ‏ ‏عِزُونَ ‏ ‏وَهِيَ حِلَقٌ ‏ ‏فَغَضِبَ فَقَالَ لَوْ أَنَّ رَجُلًا ‏ ‏نَدَى ‏ ‏النَّاسَ ‏ ‏وَقَالَ ‏ ‏عَمْرٌو ‏ ‏نَدَبَ النَّاسَ ‏ ‏إِلَى ‏ ‏عَرْقٍ ‏ ‏أَوْ ‏ ‏مِرْمَاتَيْنِ ‏ ‏لَأَجَابُوا إِلَيْهِ وَهُمْ يَتَخَلَّفُونَ عَنْ هَذِهِ الصَّلَاةِ ‏ ‏لَهَمَمْتُ أَنْ آمُرَ رَجُلًا لِيُصَلِّيَ بِالنَّاسِ ثُمَّ أَتَخَلَّفَ عَلَى أَهْلِ هَذِهِ الدُّورِ الَّذِينَ يَتَخَلَّفُونَ عَنْ هَذِهِ الصَّلَاةِ ‏ ‏فَأُضْرِمَهَا ‏ ‏عَلَيْهِمْ بِالنِّيرَانِ ‏","","",""],[1187,1187,"","","‏ ‏أَخْبَرَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعِشَاءِ حَتَّى نَادَاهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَدْ نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّهُ لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ ‏ ‏يُصَلِّي هَذِهِ الصَّلَاةَ غَيْرَكُمْ وَلَمْ يَكُنْ أَحَدٌ ‏ ‏يُصَلِّي يَوْمَئِذٍ غَيْرَ أَهْلِ ‏ ‏الْمَدِينَةِ ‏","","",""],[1188,1188,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُغِيرَةُ بْنُ حَكِيمٍ ‏ ‏أَنَّ ‏ ‏أُمَّ كُلْثُومٍ بِنْتَ أَبِي بَكْرٍ ‏ ‏أَخْبَرَتْهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ حَتَّى ذَهَبَ عَامَّةُ اللَّيْلِ وَرَقَدَ أَهْلُ الْمَسْجِدِ فَخَرَجَ فَصَلَّاهَا فَقَالَ ‏ ‏إِنَّهَا لَوَقْتُهَا لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي ‏","","",""],[1189,1189,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ بْنِ أَبِي خَلَفٍ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏ح ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَّرَ الصَّلَاةَ ذَاتَ لَيْلَةٍ فَقِيلَ يَا رَسُولَ اللَّهِ الصَّلَاةَ نَامَ النِّسَاءُ وَالْوِلْدَانُ فَخَرَجَ وَهُوَ يَمْسَحُ الْمَاءَ عَنْ شِقِّهِ وَهُوَ يَقُولُ ‏ ‏هُوَ الْوَقْتُ لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي ‏","","",""],[1190,1190,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّ نِسَاءُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّينَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَجْرَ ثُمَّ يَرْجِعْنَ ‏ ‏مُتَلَفِّعَاتٍ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏قَبْلَ أَنْ يُعْرَفْنَ ‏","","",""],[1191,1191,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَسْفِرُوا ‏ ‏بِصَلَاةِ الصُّبْحِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏","","",""],[1192,1192,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَوِّرُوا ‏ ‏بِصَلَاةِ الْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏نَحْوَهُ أَوْ ‏ ‏أَسْفِرُوا ‏","","",""],[1193,1193,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ مِنْ صَلَاةٍ رَكْعَةً فَقَدْ أَدْرَكَهَا ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[1194,1194,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏وَعَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏وَعَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏يُحَدِّثُونَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ مِنْ الصُّبْحِ رَكْعَةً قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَهَا وَمَنْ أَدْرَكَ مِنْ الْعَصْرِ رَكْعَةً قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَهَا ‏","","",""],[1195,1195,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ الْحُمَيْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتُمْ الرَّجُلَ يَعْتَادُ الْمَسَاجِدَ فَاشْهَدُوا لَهُ بِالْإِيمَانِ فَإِنَّ اللَّهَ يَقُولُ ‏ { ‏إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ ‏}","","",""],[1196,1196,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ كَانَ كَقِيَامِ نِصْفِ لَيْلَةٍ وَمَنْ صَلَّى الْفَجْرَ فِي جَمَاعَةٍ كَانَ كَقِيَامِ لَيْلَةٍ ‏","","",""],[1197,1197,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏الْوَلِيدُ بْنُ عَيْزَارٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏يَقُولُ ‏ ‏حَدَّثَنِي صَاحِبُ هَذِهِ الدَّارِ وَأَوْمَأَ بِيَدِهِ إِلَى دَارِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْعَمَلِ أَفْضَلُ أَوْ أَحَبُّ إِلَى اللَّهِ قَالَ ‏ ‏الصَّلَاةُ عَلَى مِيقَاتِهَا ‏","","",""],[1198,1198,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ هُوَ ابْنُ النُّعْمَانِ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِسْحَقَ بْنِ كَعْبِ بْنِ عُجْرَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ فِي الْمَسْجِدِ سَبْعَةٌ مِنَّا ثَلَاثَةٌ مِنْ عَرَبِنَا وَأَرْبَعَةٌ مِنْ مَوَالِينَا ‏ ‏أَوْ أَرْبَعَةٌ مِنْ عَرَبِنَا وَثَلَاثَةٌ مِنْ مَوَالِينَا ‏ ‏قَالَ فَخَرَجَ عَلَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ بَعْضِ حُجَرِهِ حَتَّى جَلَسَ إِلَيْنَا فَقَالَ ‏ ‏مَا يُجْلِسُكُمْ هَاهُنَا قُلْنَا انْتِظَارُ الصَّلَاةِ قَالَ ‏ ‏فَنَكَتَ ‏ ‏بِإِصْبَعِهِ فِي الْأَرْضِ ‏ ‏وَنَكَسَ ‏ ‏سَاعَةً ثُمَّ رَفَعَ إِلَيْنَا رَأْسَهُ فَقَالَ هَلْ تَدْرُونَ مَا يَقُولُ رَبُّكُمْ قَالَ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ إِنَّهُ يَقُولُ مَنْ صَلَّى الصَّلَاةَ لِوَقْتِهَا فَأَقَامَ حَدَّهَا كَانَ لَهُ بِهِ عَلَيَّ عَهْدٌ أُدْخِلُهُ الْجَنَّةَ وَمَنْ لَمْ يُصَلِّ الصَّلَاةَ لِوَقْتِهَا وَلَمْ يُقِمْ حَدَّهَا لَمْ يَكُنْ لَهُ عِنْدِي عَهْدٌ إِنْ شِئْتُ أَدْخَلْتُهُ النَّارَ وَإِنْ شِئْتُ أَدْخَلْتُهُ الْجَنَّةَ ‏","","",""],[1199,1199,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ الْبَرَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏كَيْفَ أَنْتَ إِذَا بَقِيتَ فِي قَوْمٍ يُؤَخِّرُونَ الصَّلَاةَ عَنْ وَقْتِهَا قَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ صَلِّ الصَّلَاةَ لِوَقْتِهَا وَاخْرُجْ فَإِنْ أُقِيمَتْ الصَّلَاةُ وَأَنْتَ فِي الْمَسْجِدِ فَصَلِّ مَعَهُمْ ‏","","",""],[1200,1200,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏كَيْفَ تَصْنَعُ إِذَا أَدْرَكْتَ أُمَرَاءَ يُؤَخِّرُونَ الصَّلَاةَ عَنْ وَقْتِهَا قُلْتُ مَا تَأْمُرُنِي يَا رَسُولَ اللَّهِ قَالَ صَلِّ الصَّلَاةَ لِوَقْتِهَا وَاجْعَلْ صَلَاتَكَ مَعَهُمْ نَافِلَةً ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏ابْنُ الصَّامِتِ ‏ ‏هُوَ ابْنُ أَخِي ‏ ‏أَبِي ذَرٍّ ‏","","",""]];
